async enroll(userId: string, courseId: string) {
  const enrollment = await this.db.transaction(async (tx) =>
    tx.enrollments.insert({ userId, courseId, status: "active" }));   // COMMIT here
  for (let attempt = 1; attempt <= 5; attempt++) {
    try {
      await this.broker.publish("enrollments", toEvent(enrollment));
      return enrollment;
    } catch (err) {
      await sleep(2 ** attempt * 100);   // 200, 400, 800, 1600, 3200 ms
    }
  }
  this.logger.warn(`gave up publishing for ${enrollment.id}`);
  return enrollment;
}

A rolling deploy sends SIGKILL to the pod right after the transaction committed, before the first publish attempt.

Statement: "The enrollment row stays committed and its enrollment.created event is never published; the retry loop cannot help, because it only exists in the process that was killed."

async enroll(userId: string, courseId: string) {
  return this.db.transaction({ isolation: "serializable" }, async (tx) => {
    await this.assertSeatAvailable(tx, courseId);
    const enrollment = await tx.enrollments.insert({ userId, courseId, status: "active" });
    await this.broker.publish("enrollments", toEvent(enrollment));
    return enrollment;
  });   // COMMIT happens when the callback returns
}

Log of one request:
10:00:41.219 DEBUG publish enrollment.created key=enr_70318 acked (9 ms)
10:00:41.224 ERROR tx COMMIT failed: could not serialize access due to read/write dependencies among transactions (SQLSTATE 40001)
10:00:41.225 INFO  POST /enrollments 409 Conflict

Statement: "Because the publish ran inside the transaction callback, the failed COMMIT also withdraws enrollment.created from the broker, so no consumer will process an event for enr_70318."
